CREATE TABLE prepaid_create_recoveries (period_id TEXT PRIMARY KEY NOT NULL REFERENCES prepaid_periods(period_id),contract_id TEXT NOT NULL REFERENCES prepaid_contracts(contract_id),intent_id TEXT NOT NULL REFERENCES purchase_intents(intent_id),scope_hash TEXT NOT NULL REFERENCES postfinance_mutations(scope_hash),request_fingerprint TEXT NOT NULL,original_claim_token TEXT NOT NULL,transaction_id INTEGER NOT NULL,observed_state TEXT NOT NULL,observed_version INTEGER NOT NULL,source_json TEXT NOT NULL,response_json TEXT NOT NULL,evidence_fingerprint TEXT NOT NULL,recovered_at INTEGER NOT NULL,CONSTRAINT prepaid_create_recovery_hash CHECK(length(scope_hash)=64 AND scope_hash NOT GLOB '*[^a-f0-9]*' AND length(evidence_fingerprint)=64 AND evidence_fingerprint NOT GLOB '*[^a-f0-9]*'),CONSTRAINT prepaid_create_recovery_request CHECK(length(request_fingerprint)=43 AND request_fingerprint NOT GLOB '*[^A-Za-z0-9_-]*' AND length(original_claim_token)=36),CONSTRAINT prepaid_create_recovery_observation CHECK(transaction_id>0 AND observed_version>=0 AND recovered_at>0 AND observed_state IN('PENDING','CONFIRMED','PROCESSING','AUTHORIZED','COMPLETED','FULFILL','FAILED','DECLINE','VOIDED')),CONSTRAINT prepaid_create_recovery_json CHECK(json_valid(source_json) AND json_type(source_json)='object' AND length(CAST(source_json AS BLOB))<=65536 AND json_valid(response_json) AND json_type(response_json)='object' AND length(CAST(response_json AS BLOB))<=262144));
--> statement-breakpoint
CREATE UNIQUE INDEX prepaid_create_recoveries_scope ON prepaid_create_recoveries(scope_hash);
--> statement-breakpoint
CREATE TRIGGER prepaid_create_recovery_closed BEFORE INSERT ON prepaid_create_recoveries BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM prepaid_transactions t JOIN prepaid_periods p ON p.period_id=t.period_id JOIN prepaid_contracts c ON c.contract_id=p.contract_id JOIN prepaid_payment_expectations e ON e.period_id=p.period_id JOIN prepaid_purchase_targets x ON x.contract_id=c.contract_id JOIN purchase_intents i ON i.intent_id=x.intent_id LEFT JOIN prepaid_renewal_requests r ON r.period_id=p.period_id WHERE (p.period_id=NEW.period_id AND c.contract_id=NEW.contract_id AND i.intent_id=NEW.intent_id AND c.environment IN('TEST','PRODUCTION') AND t.api_origin=c.api_origin AND t.space_id=c.space_id AND t.transaction_id=NEW.transaction_id) AND (c.fingerprint=json_extract(NEW.source_json,'$.contract_fingerprint') AND e.fingerprint=json_extract(NEW.source_json,'$.expectation_fingerprint') AND i.fingerprint=json_extract(NEW.source_json,'$.intent_fingerprint') AND i.parameters=json_extract(NEW.source_json,'$.parameters') AND x.previous_subscription_id IS json_extract(NEW.source_json,'$.previous_subscription_id')) AND (r.parameters IS json_extract(NEW.source_json,'$.renewal_parameters') AND r.fingerprint IS json_extract(NEW.source_json,'$.renewal_fingerprint') AND r.create_scope_hash IS json_extract(NEW.source_json,'$.create_scope_hash')) AND (c.owner_id=i.owner_id AND c.organization_id IS i.organization_id AND c.workspace_id IS i.workspace_id AND i.provider='postfinance' AND i.environment=c.environment AND i.provider_scope=(c.api_origin||'|'||c.space_id)) AND (x.owner_id=c.owner_id AND x.organization_id IS c.organization_id AND x.workspace_id IS c.workspace_id AND NEW.recovered_at>=t.created_at AND NEW.recovered_at<=unixepoch()) AND (p.ordinal=0 AND i.state IN('dispatched','uncertain') AND i.provider_reference=CAST(NEW.transaction_id AS TEXT) OR p.ordinal>0 AND i.state='settled' AND EXISTS(SELECT 1 FROM prepaid_purchase_projections v WHERE v.contract_id=c.contract_id AND v.intent_id=i.intent_id AND v.closed_at IS NOT NULL)) AND (c.organization_id IS NULL OR EXISTS(SELECT 1 FROM organizations o JOIN organization_members m ON m.organization_id=o.organization_id WHERE o.organization_id=c.organization_id AND o.created_by_user_id=c.owner_id AND m.user_id=c.owner_id AND m.role='owner' AND m.revoked_at IS NULL)) AND (c.workspace_id IS NULL OR EXISTS(SELECT 1 FROM support_workspaces w WHERE w.id=c.workspace_id AND w.owner_id=c.owner_id)) AND NOT EXISTS(SELECT 1 FROM account_session_policy a WHERE a.user_id=c.owner_id AND a.deleted_at IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM support_gestion_links l WHERE (l.organization_id=c.organization_id AND l.workspace_id IS NOT c.workspace_id AND c.workspace_id IS NOT NULL) OR (l.workspace_id=c.workspace_id AND l.organization_id IS NOT c.organization_id))) THEN RAISE(ABORT,'prepaid_create_recovery_binding') WHEN NOT EXISTS(SELECT 1 FROM postfinance_mutations m WHERE m.scope_hash=NEW.scope_hash AND m.fingerprint=NEW.request_fingerprint AND m.state='completed' AND m.claim_token IS NULL AND m.response_json=NEW.response_json AND m.updated_at=NEW.recovered_at) THEN RAISE(ABORT,'prepaid_create_recovery_cas') WHEN json_extract(NEW.response_json,'$.id') IS NOT NEW.transaction_id OR json_extract(NEW.response_json,'$.state') IS NOT NEW.observed_state OR json_extract(NEW.response_json,'$.version') IS NOT NEW.observed_version OR json_extract(NEW.response_json,'$.merchantReference') IS NOT NEW.period_id THEN RAISE(ABORT,'prepaid_create_recovery_observation') END; END;
--> statement-breakpoint
CREATE TRIGGER prepaid_create_recovery_no_update BEFORE UPDATE ON prepaid_create_recoveries BEGIN SELECT RAISE(ABORT,'prepaid_create_recovery_history'); END;
--> statement-breakpoint
CREATE TRIGGER prepaid_create_recovery_no_delete BEFORE DELETE ON prepaid_create_recoveries BEGIN SELECT RAISE(ABORT,'prepaid_create_recovery_history'); END;
